/**
 * Tests for ashlr__pipe (pipe-server.ts + pipe-server-handlers.ts).
 *
 * Run with: ASHLR_PIPE_ENABLE=1 bun test __tests__/pipe-server.test.ts
 *
 * Most tests exercise the core logic directly via ashlrPipe(); the handler
 * regression test also exercises the router over MCP stdio. Registry-based
 * ctx calls use real handlers where feasible and stubs for accounting tests.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "fs/promises";
import { tmpdir } from "os";
import { join } from "path";
import { timingBudgetMs } from "../scripts/timing-budget.ts";

// NOTE: we deliberately do NOT set process.env.ASHLR_PIPE_ENABLE here. That env
// var only gates *registration* of ashlr__pipe in pipe-server-handlers.ts; the
// core ashlrPipe() function under test needs no flag. Setting it at module scope
// leaks process-wide and makes sibling test files that import _router-handlers
// register a 41st tool, breaking the tool-count assertions. See router-dispatch
// + product-metadata tests.

import { ashlrPipe, type PipeResult } from "../servers/pipe-server";
import {
  registerTool,
  __snapshotRegistryForTests,
  __restoreRegistryForTests,
  type ToolCallContext,
} from "../servers/_tool-base";
import { _withSuppressedAccounting, _isAccountingSuppressed } from "../servers/_stats";

describe("ashlr__pipe · handler error isolation", () => {
  test("invalid JavaScript returns tool errors and the server handles later calls, including grep with no matches", async () => {
    const fixture = join(home, "grep-fixture.txt");
    await writeFile(fixture, "needle first: complete text\nunrelated line\nneedle second: complete text\nneedle third: complete text\n");
    const proc = Bun.spawn({
      cmd: [process.execPath, "run", join(import.meta.dir, "../servers/_router.ts")],
      cwd: join(import.meta.dir, ".."),
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
      env: {
        ...process.env,
        HOME: home,
        ASHLR_PIPE_ENABLE: "1",
        ASHLR_STATS_SYNC: "1",
        ASHLR_SESSION_LOG: "0",
        ASHLR_CONTEXT_DB_DISABLE: "1",
        ASHLR_ALLOW_PROJECT_PATHS: home,
        ASHLR_GENOME_RETRIEVAL: "off",
      },
    });
    const reader = proc.stdout.getReader();
    const stderr = new Response(proc.stderr).text();
    const decoder = new TextDecoder();
    let pending = "";
    async function request(id: number, method: string, params: unknown) {
      proc.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
      while (!pending.includes("\n")) {
        const chunk = await reader.read();
        if (chunk.done) throw new Error(`router exited before response ${id}`);
        pending += decoder.decode(chunk.value, { stream: true });
      }
      const newline = pending.indexOf("\n");
      const response = JSON.parse(pending.slice(0, newline));
      pending = pending.slice(newline + 1);
      expect(response.id).toBe(id);
      return response;
    }

    try {
      const init = await request(1, "initialize", {
        protocolVersion: "2024-11-05",
        capabilities: {},
        clientInfo: { name: "pipe-test", version: "1" },
      });
      expect(init.result.serverInfo.name).toBe("ashlr-router");

      for (const [id, expr] of [[2, "return ("], [3, "const value = ;"]] as const) {
        const response = await request(id, "tools/call", {
          name: "ashlr__pipe",
          arguments: { expr },
        });
        expect(response.error).toBeUndefined();
        expect(response.result.isError).toBe(true);
        expect(response.result.content).toHaveLength(1);
        expect(response.result.content[0].type).toBe("text");
        expect(response.result.content[0].text).toStartWith("ashlr__pipe error: ");
        expect(response.result.content[0].text.length).toBeGreaterThan("ashlr__pipe error: ".length);
      }

      const response = await request(4, "tools/call", {
        name: "ashlr__pipe",
        arguments: { expr: "return 42;" },
      });
      expect(response.result.isError).not.toBe(true);
      expect(response.result.content).toEqual([{ type: "text", text: "42" }]);

      const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
      const section = doc.split("### Replace repeated matches in text")[1].split("## Savings accounting")[0];
      const { expr } = JSON.parse(section.match(/```json\n([\s\S]*?)\n```/)![1]) as { expr: string };
      const replacement = await request(5, "tools/call", {
        name: "ashlr__pipe",
        arguments: { expr },
      });
      expect(replacement.error).toBeUndefined();
      expect(replacement.result.isError).not.toBe(true);
      expect(replacement.result.content).toEqual([
        { type: "text", text: JSON.stringify("DONE first; DONE second; DONE") },
      ]);

      const zero = await request(6, "tools/call", {
        name: "ashlr__pipe",
        arguments: { expr: "return 0;" },
      });
      expect(zero.error).toBeUndefined();
      expect(zero.result.isError).not.toBe(true);
      expect(zero.result.content).toEqual([{ type: "text", text: "0" }]);

      const empty = await request(7, "tools/call", {
        name: "ashlr__pipe",
        arguments: { expr: "return \"\";" },
      });
      expect(empty.error).toBeUndefined();
      expect(empty.result.isError).not.toBe(true);
      expect(empty.result.content).toEqual([{ type: "text", text: "\"\"" }]);

      const grepArgs = { pattern: "absent-needle", cwd: fixture, bypassSummary: true };
      const grep = await request(8, "tools/call", { name: "ashlr__grep", arguments: grepArgs });
      expect(grep.error).toBeUndefined();
      expect(grep.result.isError).not.toBe(true);
      const grepText = grep.result.content[0].text;
      expect(typeof grepText).toBe("string");
      expect(grepText).toStartWith("[no matches]");

      const noMatches = await request(9, "tools/call", {
        name: "ashlr__pipe",
        arguments: { expr: `return await ctx.grep(${JSON.stringify(grepArgs)});` },
      });
      expect(noMatches.error).toBeUndefined();
      expect(noMatches.result.isError).not.toBe(true);
      const value = JSON.parse(noMatches.result.content[0].text);
      expect(typeof value).toBe("string");
      expect(value).toBe(grepText);

      const multiArgs = { pattern: "needle", cwd: fixture, bypassSummary: true };
      const direct = await request(10, "tools/call", { name: "ashlr__grep", arguments: multiArgs });
      expect(direct.error).toBeUndefined();
      expect(direct.result.isError).not.toBe(true);
      const directText = direct.result.content[0].text;
      const matchingLines = directText.split("\n").filter((line: string) => line.includes("needle"));
      expect(matchingLines).toEqual([
        "1:needle first: complete text",
        "3:needle second: complete text",
        "4:needle third: complete text",
      ]);

      const multi = await request(11, "tools/call", {
        name: "ashlr__pipe",
        arguments: { expr: `return await ctx.grep(${JSON.stringify(multiArgs)});` },
      });
      expect(multi.error).toBeUndefined();
      expect(multi.result.isError).not.toBe(true);
      expect(multi.result.content).toHaveLength(1);
      expect(multi.result.content[0].type).toBe("text");
      const multiValue = JSON.parse(multi.result.content[0].text);
      expect(typeof multiValue).toBe("string");
      expect(multiValue).toBe(directText);
    } finally {
      proc.kill();
      await proc.exited;
      reader.releaseLock();
      await stderr;
    }
  }, timingBudgetMs(10_000));
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeCtx(home: string): ToolCallContext {
  return {
    sessionId: "test-pipe-session",
    env: { ...process.env, HOME: home },
  };
}

// Minimal stub handler that records whether it was called and returns a fixed
// string. Used to verify suppress-accounting behavior without invoking real tools.
function makeStubHandler(returnText: string, callLog: string[]) {
  return async (args: Record<string, unknown>, _ctx: ToolCallContext) => {
    callLog.push(JSON.stringify(args));
    return { content: [{ type: "text" as const, text: returnText }] };
  };
}

// ---------------------------------------------------------------------------
// Setup / teardown
// ---------------------------------------------------------------------------

let home: string;
let snap: ReturnType<typeof __snapshotRegistryForTests>;

beforeEach(async () => {
  home = await mkdtemp(join(tmpdir(), "ashlr-pipe-test-"));
  snap = __snapshotRegistryForTests();
});

afterEach(async () => {
  __restoreRegistryForTests(snap);
  await rm(home, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// Suite 1: basic execution
// ---------------------------------------------------------------------------

describe("ashlr__pipe · basic execution", () => {
  test("documented nonempty grep-line count handles trailing newlines and status text", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const section = doc.split("### Count nonempty grep-result lines")[1]?.split("### Show a fallback")[0];
    expect(section).toBeDefined();
    const { expr } = JSON.parse(section!.match(/```json\n([\s\S]*?)\n```/)![1]) as { expr: string };
    const calls: string[] = [];

    for (const [input, expected] of [
      ["src/app.ts:3:TODO first\nsrc/config.ts:8:TODO second\n", 2],
      ["src/app.ts:3:TODO first\nsrc/config.ts:8:TODO second", 2],
      ["", 0],
      ["\n\n", 0],
      ["first\n\nsecond\n", 2],
      [" \n[no matches]\n", 2],
    ] as const) {
      registerTool({ name: "ashlr__grep", description: "stub", inputSchema: {}, handler: makeStubHandler(input, calls) });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toBe(expected);
    }
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(6).fill({ pattern: "TODO", cwd: ".", bypassSummary: true }),
    );
  });

  test("documented no-match example falls back only for empty or bare no-match output", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const section = doc.split("### Show a fallback for an empty grep result")[1]?.split("### Keep the grep response")[0];
    expect(section).toBeDefined();
    const blocks = [...section!.matchAll(/```json\n([\s\S]*?)\n```/g)];
    expect(blocks).toHaveLength(2);
    const { expr } = JSON.parse(blocks[0][1]) as { expr: string };
    const fallback = JSON.parse(blocks[1][1]);
    expect(fallback).toBe("No TODOs found");
    const calls: string[] = [];

    for (const [input, expected] of [
      ["", fallback],
      [" \n", fallback],
      ["[no matches]\n", fallback],
      ["src/app.ts:3:TODO fix\n", "src/app.ts:3:TODO fix\n"],
      ["[no matches]\n[ashlr] status", "[no matches]\n[ashlr] status"],
      ["search unavailable", "search unavailable"],
    ]) {
      registerTool({ name: "ashlr__grep", description: "stub", inputSchema: {}, handler: makeStubHandler(input, calls) });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toBe(expected);
    }
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(6).fill({ pattern: "TODO", cwd: ".", bypassSummary: true }),
    );
  });

  test("documented grep entries retain the response, including when empty", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const section = doc.split("### Keep the grep response alongside file-and-line entries")[1]?.split("### Count matching lines")[0];
    expect(section).toBeDefined();
    const blocks = [...section!.matchAll(/```json\n([\s\S]*?)\n```/g)];
    expect(blocks).toHaveLength(2);
    const { expr } = JSON.parse(blocks[0][1]) as { expr: string };
    const emptyExpected = JSON.parse(blocks[1][1]);
    const calls: string[] = [];
    const many = Array.from({ length: 22 }, (_, i) => `file-${i}.ts:${i + 1}:TODO`).join("\n");

    for (const [input, files] of [
      ["", []],
      ["[no matches]\n", []],
      ["status: search unavailable\n", []],
      ["my project/a.ts:9:TODO\n[ashlr confidence: low]\n", ["my project/a.ts:9"]],
      ["drive:project/a.ts:2:TODO\n", ["drive:project/a.ts:2"]],
      ["z.ts:7:TODO first\n\n\na.ts:2:TODO second\n\nm.ts:4:TODO third\n", ["z.ts:7", "a.ts:2", "m.ts:4"]],
      [many, Array.from({ length: 20 }, (_, i) => `file-${i}.ts:${i + 1}`)],
    ] as const) {
      registerTool({ name: "ashlr__grep", description: "stub", inputSchema: {}, handler: makeStubHandler(input, calls) });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toEqual({ files, raw: input });
    }
    expect(emptyExpected).toEqual({ files: [], raw: "" });
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(7).fill({ pattern: "TODO", cwd: ".", bypassSummary: true }),
    );
  });

  test("documented count example counts matching lines in grep text", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const section = doc.split("### Count matching lines")[1]?.split("### Replace repeated matches")[0];
    expect(section).toBeDefined();
    const blocks = [...section!.matchAll(/```(json|text)\n([\s\S]*?)\n```/g)];
    expect(blocks.map((block) => block[1])).toEqual(["json", "text"]);
    const { expr } = JSON.parse(blocks[0][2]) as { expr: string };
    expect(section).toContain("the pipe returns `2`");
    const calls: string[] = [];

    for (const [input, expected] of [
      [blocks[1][2] + "\n", 2],
      ["", 0],
      ["[no matches]\n", 0],
      ["a.ts:1:TODO TODO\n\nother\nb.ts:2:TODO\n", 2],
      ["status: TODO search unavailable\n", 0],
      ["TODO-file.ts:1:unrelated\n", 0],
      ["[embedding-cache hit | sim=0.953 | grep:TODO]\nmy project/a.ts:9:TODO\n", 1],
      ["status:42:TODO search unavailable\n", 1],
    ] as const) {
      registerTool({
        name: "ashlr__grep",
        description: "stub",
        inputSchema: {},
        handler: makeStubHandler(input, calls),
      });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toBe(expected);
    }
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(8).fill({ pattern: "TODO", cwd: ".", bypassSummary: true }),
    );
  });

  test("documented empty-line filter returns the illustrated lines", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const example = doc.split("### Filter empty grep-result lines")[1].split("### Example 1")[0];
    const blocks = [...example.matchAll(/```(json|text)\n([\s\S]*?)\n```/g)];
    expect(blocks.map((block) => block[1])).toEqual(["json", "text", "json"]);
    const { expr } = JSON.parse(blocks[0][2]) as { expr: string };
    const expected = JSON.parse(blocks[2][2]);
    const calls: string[] = [];

    for (const [input, output] of [
      [blocks[1][2] + "\n", expected],
      ["", []],
      ["\n  \nNo matches found.\n", ["  ", "No matches found."]],
    ] as const) {
      registerTool({
        name: "ashlr__grep",
        description: "stub",
        inputSchema: {},
        handler: makeStubHandler(input, calls),
      });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toEqual(output);
    }
    expect(expected).toEqual(["src/app.ts:3:TODO first", "src/config.ts:8:TODO second"]);
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(3).fill({ pattern: "TODO", cwd: ".", bypassSummary: true }),
    );
  });

  test("documented direct grep example returns tool text from the specified directory", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const section = doc.split("### Return grep output from a working directory")[1]?.split("### Example 1")[0];
    expect(section).toBeDefined();
    const { expr } = JSON.parse(section!.match(/```json\n([\s\S]*?)\n```/)![1]) as { expr: string };
    const callLog: string[] = [];

    for (const grepText of ["my project/file.ts:1:TODO", "No matches found."]) {
      registerTool({
        name: "ashlr__grep",
        description: "stub",
        inputSchema: {},
        handler: makeStubHandler(grepText, callLog),
      });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toBe(grepText);
    }
    expect(callLog.map((args) => JSON.parse(args))).toEqual([
      { pattern: "TODO", cwd: "my project" },
      { pattern: "TODO", cwd: "my project" },
    ]);
  });

  test("the advertised grep example accepts a path with spaces and returns tool text", async () => {
    const catalog = JSON.parse(await readFile(join(import.meta.dir, "../servers/_tool-catalog.json"), "utf8")) as Array<{
      name: string;
      description: string;
    }>;
    const description = catalog.find((tool) => tool.name === "ashlr__pipe")!.description;
    const expr = description.match(/Example: `([^`]+)`/)?.[1];
    expect(expr).toBeDefined();
    expect(description).toContain("returns the grep tool's text output as a string, which may include status messages");

    const callLog: string[] = [];
    const grepText = "[ashlr__grep] status\nmy project/file.ts:1:TODO";
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler(grepText, callLog),
    });

    const result = await ashlrPipe({ expr: expr! }, makeCtx(home));
    expect(JSON.parse(result.text)).toBe(grepText);
    expect(callLog.map((args) => JSON.parse(args))).toEqual([{ pattern: "TODO", cwd: "my project" }]);
  });

  test("pipe server grep page reproduces the handler example and returns its text", async () => {
    const handler = await readFile(join(import.meta.dir, "../servers/pipe-server-handlers.ts"), "utf8");
    const advertised = handler.match(/Example: `([^`]+)`/)?.[1];
    const doc = await readFile(join(import.meta.dir, "../docs/pipe-server-grep-example.md"), "utf8");
    const blocks = [...doc.matchAll(/```json\n([\s\S]*?)\n```/g)];
    expect(blocks).toHaveLength(2);
    const { expr } = JSON.parse(blocks[0][1]) as { expr: string };
    expect(advertised).toBeDefined();
    expect(advertised).toBe(expr);

    const calls: string[] = [];
    const illustrated = "src/app.ts:3:TODO fix this\n";
    for (const text of [illustrated, "src/z.ts:9:TODO first\nsrc/a.ts:2:TODO second\nsrc/m.ts:7:TODO third\n", "[no matches]\n[ashlr] status", "error: directory unavailable"]) {
      registerTool({ name: "ashlr__grep", description: "stub", inputSchema: {}, handler: makeStubHandler(text, calls) });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toBe(text);
      if (text === illustrated) expect(result.text).toBe(blocks[1][1]);
    }
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(4).fill({ pattern: "TODO", cwd: "my project" }),
    );
  });

  test("documented TODO example returns the illustrated file and line pairs", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const example = doc.split("### Example 1")[1].split("### Example 2")[0];
    const blocks = [...example.matchAll(/```(json|text)\n([\s\S]*?)\n```/g)];
    expect(blocks.map((block) => block[1])).toEqual(["json", "text", "json"]);
    const { expr } = JSON.parse(blocks[0][2]) as { expr: string };
    const expected = JSON.parse(blocks[2][2]);
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler(blocks[1][2] + "\n", callLog),
    });

    const result = await ashlrPipe({ expr }, makeCtx(home));
    expect(JSON.parse(result.text)).toEqual(expected);
    expect(expected).toEqual(["/project/src/app.ts:42", "/project/src/config.ts:7"]);
    expect(JSON.parse(callLog[0])).toEqual({ pattern: "TODO", cwd: ".", bypassSummary: true });
  });

  test("documented TODO example splits text, filters lines, and limits results", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const example = doc.split("### Example 1")[1].split("### Example 2")[0];
    const { expr } = JSON.parse(example.match(/```json\n([\s\S]*?)\n```/)![1]) as { expr: string };
    const matches = Array.from({ length: 22 }, (_, i) => `file-${i}.ts:${i + 1}:TODO: task`);
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler(["no colon", "", ...matches, ""].join("\n"), callLog),
    });

    const result = await ashlrPipe({ expr }, makeCtx(home));
    expect(JSON.parse(result.text)).toEqual(matches.slice(0, 20).map((_, i) => `file-${i}.ts:${i + 1}`));

    for (const text of ["", "no matches\n"]) {
      registerTool({
        name: "ashlr__grep",
        description: "stub",
        inputSchema: {},
        handler: makeStubHandler(text, callLog),
      });
      const empty = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(empty.text)).toEqual([]);
    }

    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler("status: search unavailable\n", callLog),
    });
    const status = await ashlrPipe({ expr }, makeCtx(home));
    expect(JSON.parse(status.text)).toEqual(["status: search unavailable"]);
  });

  test("documented empty-result example filters status lines and returns [] on empty output", async () => {
    const doc = await readFile(join(import.meta.dir, "../docs/ashlr-pipe.md"), "utf8");
    const example = doc
      .split("### Example 2 — grep for TODOs with an empty-result check")[1]
      ?.split("### Example 3")[0];
    expect(example).toBeDefined();
    const blocks = [...example!.matchAll(/```(json|text)\n([\s\S]*?)\n```/g)];
    expect(blocks.map((block) => block[1])).toEqual(["json", "json", "text", "json"]);
    const { expr } = JSON.parse(blocks[0][2]) as { expr: string };
    const emptyExpected = JSON.parse(blocks[1][2]);
    const expected = JSON.parse(blocks[3][2]);
    const callLog: string[] = [];

    for (const [input, output] of [
      [blocks[2][2] + "\n", expected],
      ["", emptyExpected],
      ["[no matches]\n", []],
      ["[no matches]\n[ashlr confidence: low · bypassSummary:true to recover fidelity]\n", []],
      ["status: search unavailable\n", []],
      ["[ashlr confidence: low · bypassSummary:true to recover fidelity]\n", []],
      ["[embedding-cache hit | sim=0.953 | grep:TODO]\na.ts:9:TODO\n", ["a.ts:9"]],
      ["my project/file.ts:1:TODO\n", ["my project/file.ts:1"]],
      ["a.ts:1:TODO one\nstatus: search unavailable\nb.ts:2:TODO two\n", ["a.ts:1", "b.ts:2"]],
      ["status:42: search unavailable\n", ["status:42"]],
    ] as const) {
      registerTool({
        name: "ashlr__grep",
        description: "stub",
        inputSchema: {},
        handler: makeStubHandler(input, callLog),
      });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toEqual(output);
    }
    expect(expected).toEqual(["/project/src/app.ts:42"]);
    expect(emptyExpected).toEqual([]);
    expect(callLog.map((args) => JSON.parse(args))).toEqual(
      Array(10).fill({ pattern: "TODO", cwd: ".", bypassSummary: true }),
    );
  });

  test("multi-step pipe returns only the final value, not intermediates", async () => {
    // Register stub tools that return recognizable strings.
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler("grep-result-line-1\ngrep-result-line-2", callLog),
    });

    const ctx = makeCtx(home);
    const expr = `
      const grepOut = await ctx.grep({ pattern: "TODO", cwd: "." });
      const lines = grepOut.split("\\n").filter(Boolean);
      return lines.length;
    `;
    const result = await ashlrPipe({ expr }, ctx);

    // Final value is the line count (2), not the raw grep text.
    expect(result.text).toBe("2");
    // The grep was called.
    expect(callLog.length).toBe(1);
    // rawIntermediate reflects the stub response size, not 0.
    expect(result.rawIntermediate).toBeGreaterThan(0);
  });

  test("counts nonempty grep lines when output ends with a newline", async () => {
    const calls: string[] = [];
    const expr = `
      const output = await ctx.grep({ pattern: "TODO", cwd: "." });
      return output.split("\\n").filter(Boolean).length;
    `;

    for (const [output, count] of [
      ["a.ts:1:TODO\nb.ts:2:TODO\n", 2],
      ["a.ts:1:TODO\n\nb.ts:2:TODO\n\n", 2],
      ["a.ts:1:TODO\nb.ts:2:TODO", 2],
      ["", 0],
      ["\n", 0],
    ] as const) {
      registerTool({
        name: "ashlr__grep",
        description: "stub",
        inputSchema: {},
        handler: makeStubHandler(output, calls),
      });
      const result = await ashlrPipe({ expr }, makeCtx(home));
      expect(JSON.parse(result.text)).toBe(count);
    }
    expect(calls.map((args) => JSON.parse(args))).toEqual(
      Array(5).fill({ pattern: "TODO", cwd: "." }),
    );
  });

  test("filters multiple TODO matches in their original order", async () => {
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler(
        [
          "notes.ts:1: completed task",
          "z.ts:8: TODO first task",
          "notes.ts:2: unrelated task",
          "a.ts:3: TODO second task",
          "m.ts:5: TODO third task",
          "notes.ts:4: another completed task",
        ].join("\n"),
        callLog,
      ),
    });

    const expr = `
      const output = await ctx.grep({ pattern: "task", cwd: "." });
      return output.split("\\n").filter(line => line.includes("TODO"));
    `;
    const result = await ashlrPipe({ expr }, makeCtx(home));

    expect(JSON.parse(result.text)).toEqual([
      "z.ts:8: TODO first task",
      "a.ts:3: TODO second task",
      "m.ts:5: TODO third task",
    ]);
    expect(callLog.map((args) => JSON.parse(args))).toEqual([{ pattern: "task", cwd: "." }]);
  });

  test("expr returning a plain string is serialized as JSON string", async () => {
    const ctx = makeCtx(home);
    const result = await ashlrPipe({ expr: `return "hello world";` }, ctx);
    expect(result.text).toBe('"hello world"');
  });

  test("expr returning an object is serialized as JSON", async () => {
    const ctx = makeCtx(home);
    const result = await ashlrPipe({ expr: `return { count: 42, ok: true };` }, ctx);
    const parsed = JSON.parse(result.text);
    expect(parsed).toEqual({ count: 42, ok: true });
  });

  test("expr returning numeric zero is serialized as zero", async () => {
    const result = await ashlrPipe({ expr: "return 0;" }, makeCtx(home));
    expect(result.text).toBe("0");
    expect(JSON.parse(result.text)).toBe(0);
  });

  test("expr returning an empty string preserves the empty result (not an execution error)", async () => {
    const ctx = makeCtx(home);
    const result = await ashlrPipe({ expr: `return "";` }, ctx);
    expect(result.text).toBe('""');
    expect(JSON.parse(result.text)).toBe("");
    expect(result.rawIntermediate).toBe(0);
  });

  test("expr returning an empty intermediate result preserves the empty string", async () => {
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler("", callLog),
    });
    const ctx = makeCtx(home);
    const result = await ashlrPipe(
      { expr: `return await ctx.grep({ pattern: "x" });` },
      ctx,
    );
    expect(result.text).toBe('""');
    expect(JSON.parse(result.text)).toBe("");
    expect(callLog).toHaveLength(1);
  });

  test("expr returning undefined serializes as null (JSON.stringify(undefined) ?? 'null')", async () => {
    const ctx = makeCtx(home);
    const result = await ashlrPipe({ expr: `return undefined;` }, ctx);
    expect(result.text).toBe("null");
  });
});

// ---------------------------------------------------------------------------
// Suite 2: security — deny-list
// ---------------------------------------------------------------------------

describe("ashlr__pipe · security deny-list", () => {
  const ctx = () => makeCtx(home);

  test("expr containing 'process' is rejected without execution", async () => {
    let executed = false;
    const expr = `executed = true; return process.env.HOME;`;
    try {
      await ashlrPipe({ expr }, ctx());
      expect(true).toBe(false); // should not reach
    } catch (err) {
      const msg = (err as Error).message;
      expect(msg).toContain("disallowed token");
      expect(msg).toContain("process");
      expect(executed).toBe(false);
    }
  });

  test("expr containing 'Bun' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `return Bun.version;` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("expr containing 'eval' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `return eval("1+1");` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("expr containing 'import(' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `const m = await import("fs"); return m;` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("expr containing 'globalThis' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `return globalThis.process;` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("expr containing 'fetch(' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `return await fetch("https://example.com");` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("expr containing 'Function(' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `return new Function("return 1")();` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("expr containing 'require' is rejected", async () => {
    await expect(
      ashlrPipe({ expr: `return require("fs");` }, ctx()),
    ).rejects.toThrow("disallowed token");
  });

  test("strict mode: `this` is undefined (no global escape via token-splitting)", async () => {
    // In sloppy mode `this` would be globalThis, letting `this["pro"+"cess"]`
    // bypass the substring deny-list. Strict mode makes `this` undefined.
    const result = await ashlrPipe({ expr: `return typeof this;` }, ctx());
    expect(result.text).toBe('"undefined"');
  });

  test("strict mode: reaching a global via `this` throws, not leaks", async () => {
    // `this["pro"+"cess"]` passes the deny-list (no literal "process" token)
    // but must fail at runtime because `this` is undefined under strict mode.
    await expect(
      ashlrPipe({ expr: `return this["pro" + "cess"].env;` }, ctx()),
    ).rejects.toThrow();
  });
});

// ---------------------------------------------------------------------------
// Suite 3: length limit
// ---------------------------------------------------------------------------

describe("ashlr__pipe · length limit", () => {
  test("expr > 2000 chars is rejected", async () => {
    const expr = "x".repeat(2001);
    await expect(
      ashlrPipe({ expr }, makeCtx(home)),
    ).rejects.toThrow("exceeds 2000 characters");
  });

  test("expr exactly 2000 chars is accepted (return value only matters for length)", async () => {
    // Build a 2000-char expr that returns a simple value.
    const padded = "// " + " ".repeat(1987) + "\nreturn 1;"; // 3 + 1987 + 1 + 9 = 2000
    expect(padded.length).toBe(2000);
    const result = await ashlrPipe({ expr: padded }, makeCtx(home));
    expect(result.text).toBe("1");
  });
});

// ---------------------------------------------------------------------------
// Suite 4: non-serializable return value
// ---------------------------------------------------------------------------

describe("ashlr__pipe · non-serializable return", () => {
  test("circular reference returns sentinel string", async () => {
    const ctx = makeCtx(home);
    const expr = `
      const o = {};
      o.self = o;
      return o;
    `;
    const result = await ashlrPipe({ expr }, ctx);
    expect(result.text).toBe("[non-serializable result]");
  }, timingBudgetMs(5_000));
});

// ---------------------------------------------------------------------------
// Suite 5: output truncation
// ---------------------------------------------------------------------------

describe("ashlr__pipe · output truncation", () => {
  test("output is truncated to max_output_bytes", async () => {
    const ctx = makeCtx(home);
    // Generate a 500-byte string in the expression.
    const expr = `return "x".repeat(500);`;
    const result = await ashlrPipe({ expr, max_output_bytes: 20 }, ctx);
    // Output will be JSON ("xxx...") so it starts with a quote.
    // The truncation marker is appended after the slice.
    expect(Buffer.byteLength(result.text, "utf8")).toBeGreaterThan(0);
    expect(result.text).toContain("[ashlr__pipe: output truncated]");
    // The actual content portion must be <= max_output_bytes.
    const contentPart = result.text.replace("\n[ashlr__pipe: output truncated]", "");
    expect(Buffer.byteLength(contentPart, "utf8")).toBeLessThanOrEqual(20);
  });

  test("output within max_output_bytes is not truncated", async () => {
    const ctx = makeCtx(home);
    const result = await ashlrPipe(
      { expr: `return "short";`, max_output_bytes: 4096 },
      ctx,
    );
    expect(result.text).not.toContain("truncated");
    expect(result.text).toBe('"short"');
  });
});

// ---------------------------------------------------------------------------
// Suite 6: savings accounting — intermediate calls don't double-count
// ---------------------------------------------------------------------------

describe("ashlr__pipe · savings accounting", () => {
  test("intermediate ctx calls do not double-count: aggregate rawIntermediate reflects sum", async () => {
    // Register two stub tools with known output sizes.
    const grepText = "a".repeat(1000); // 1000 bytes
    const readText = "b".repeat(500);  // 500 bytes

    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler(grepText, []),
    });
    registerTool({
      name: "ashlr__read",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler(readText, []),
    });

    const ctx = makeCtx(home);
    const expr = `
      const g = await ctx.grep({ pattern: "x" });
      const r = await ctx.read({ path: "." });
      return { gLen: g.length, rLen: r.length };
    `;

    const result = await ashlrPipe({ expr }, ctx);

    // rawIntermediate should equal the sum of the two stub outputs.
    expect(result.rawIntermediate).toBe(1500);

    // Final output should be the serialized return object, not the raw strings.
    const parsed = JSON.parse(result.text);
    expect(parsed.gLen).toBe(1000);
    expect(parsed.rLen).toBe(500);
  });

  test("a throwing intermediate handler propagates as a pipe error", async () => {
    registerTool({
      name: "ashlr__grep",
      description: "stub-throwing",
      inputSchema: {},
      handler: async () => {
        throw new Error("stub error");
      },
    });

    const ctx = makeCtx(home);
    await expect(
      ashlrPipe({ expr: `await ctx.grep({ pattern: "x" }); return 1;` }, ctx),
    ).rejects.toThrow("stub error");
  });

  test("suppression is async-scoped, not a process-global flag", async () => {
    // Regression guard for the cross-test contamination a process-global
    // suppress flag caused (it flakily zeroed the orient savings test): the
    // suppression must apply ONLY inside the pipe's async scope, never leak to
    // concurrent unrelated work. Uses introspection (no real recordSaving
    // writes, so this test can't pollute other suites' stats.json under Bun's
    // concurrent test-file scheduling).
    const inside = await _withSuppressedAccounting(() => _isAccountingSuppressed());
    expect(inside).toBe(true);
    // Outside the scope, suppression is not active.
    expect(_isAccountingSuppressed()).toBe(false);
    // A suppressed scope and an unsuppressed call in parallel keep separate stores.
    const [a, b] = await Promise.all([
      _withSuppressedAccounting(() => _isAccountingSuppressed()),
      Promise.resolve(_isAccountingSuppressed()),
    ]);
    expect(a).toBe(true);
    expect(b).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// Suite 7: timeout
// ---------------------------------------------------------------------------

describe("ashlr__pipe · timeout", () => {
  test("expr that exceeds timeout_ms is rejected with a timeout error", async () => {
    // Register a stub bash that never resolves — the 200ms pipe timeout must win.
    // We can't use setTimeout in the expr (deny-list), so we delegate to a
    // stub bash handler that awaits a real JS promise inside the handler itself.
    registerTool({
      name: "ashlr__bash",
      description: "slow-stub",
      inputSchema: {},
      handler: async () => {
        // Hang inside the handler — the pipe deadline races against this.
        await new Promise<never>(() => {});
        return { content: [{ type: "text" as const, text: "done" }] };
      },
    });

    // Enable ctx.bash for this test only — restore in finally to avoid leaking
    // into sibling tests.
    const prev = process.env.ASHLR_PIPE_ALLOW_BASH;
    process.env.ASHLR_PIPE_ALLOW_BASH = "1";
    let result: Error | PipeResult;
    try {
      const ctx = makeCtx(home);
      // Expr calls the slow bash stub — pipe timeout fires first.
      const expr = `await ctx.bash({ command: "hang" }); return "done";`;
      result = await ashlrPipe({ expr, timeout_ms: 200 }, ctx).catch((e: Error) => e);
    } finally {
      if (prev === undefined) delete process.env.ASHLR_PIPE_ALLOW_BASH;
      else process.env.ASHLR_PIPE_ALLOW_BASH = prev;
    }

    expect(result!).toBeInstanceOf(Error);
    expect((result! as Error).message).toContain("timed out after 200ms");
  }, 5000);
});

// ---------------------------------------------------------------------------
// Suite 8: real registry integration (bash with echo)
// ---------------------------------------------------------------------------

describe("ashlr__pipe · real registry integration", () => {
  test("ctx.bash with echo returns the expected text and records aggregate saving", async () => {
    // Import all handlers to populate the registry with real tools.
    await import("../servers/_router-handlers");

    const ctx = makeCtx(home);
    const tmpFile = join(home, "hello.txt");
    await writeFile(tmpFile, "hello from pipe\n");

    // Enable ctx.bash for this test only — restore in finally.
    const prev = process.env.ASHLR_PIPE_ALLOW_BASH;
    process.env.ASHLR_PIPE_ALLOW_BASH = "1";
    let result: PipeResult;
    try {
      // Use bash to cat the file we just wrote — no deny-list tokens in expr.
      const expr = `
        const out = await ctx.bash({ command: "cat ${tmpFile}" });
        return out.trim().split("\\n")[0];
      `;
      result = await ashlrPipe({ expr }, ctx);
    } finally {
      if (prev === undefined) delete process.env.ASHLR_PIPE_ALLOW_BASH;
      else process.env.ASHLR_PIPE_ALLOW_BASH = prev;
    }

    // The bash output contains the echo text — last non-empty part of parsed JSON.
    const parsed = JSON.parse(result!.text) as string;
    // bash output includes header/footer lines; our expression takes split()[0]
    // which may be the header line "$ cat ...", but rawIntermediate > 0 confirms
    // that accounting was collected.
    expect(typeof parsed).toBe("string");
    expect(result!.rawIntermediate).toBeGreaterThan(0);
  }, 10_000);
});

// ---------------------------------------------------------------------------
// Suite 9: ctx.bash gating — ASHLR_PIPE_ALLOW_BASH
// ---------------------------------------------------------------------------

describe("ashlr__pipe · ctx.bash gating", () => {
  test("ctx.bash is unavailable by default — calling it throws a clear error", async () => {
    // Ensure flag is absent for this test. Restore in finally.
    const prev = process.env.ASHLR_PIPE_ALLOW_BASH;
    delete process.env.ASHLR_PIPE_ALLOW_BASH;
    try {
      const ctx = makeCtx(home);
      // Expression calls ctx.bash — no ASHLR_PIPE_ALLOW_BASH set.
      const expr = `await ctx.bash({ command: "echo hi" }); return "done";`;
      await expect(ashlrPipe({ expr }, ctx)).rejects.toThrow(
        "ctx.bash is disabled; set ASHLR_PIPE_ALLOW_BASH=1 to enable shell access in pipes",
      );
    } finally {
      if (prev === undefined) delete process.env.ASHLR_PIPE_ALLOW_BASH;
      else process.env.ASHLR_PIPE_ALLOW_BASH = prev;
    }
  });

  test("ctx.bash is unavailable when ASHLR_PIPE_ALLOW_BASH is set to a non-'1' value", async () => {
    const prev = process.env.ASHLR_PIPE_ALLOW_BASH;
    process.env.ASHLR_PIPE_ALLOW_BASH = "true"; // not "1"
    try {
      const ctx = makeCtx(home);
      const expr = `await ctx.bash({ command: "echo hi" }); return "done";`;
      await expect(ashlrPipe({ expr }, ctx)).rejects.toThrow("ctx.bash is disabled");
    } finally {
      if (prev === undefined) delete process.env.ASHLR_PIPE_ALLOW_BASH;
      else process.env.ASHLR_PIPE_ALLOW_BASH = prev;
    }
  });

  test("ctx.bash is available when ASHLR_PIPE_ALLOW_BASH=1 — stub handler is called", async () => {
    // Register a stub bash handler.
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__bash",
      description: "stub-bash",
      inputSchema: {},
      handler: makeStubHandler("stub-bash-output", callLog),
    });

    const prev = process.env.ASHLR_PIPE_ALLOW_BASH;
    process.env.ASHLR_PIPE_ALLOW_BASH = "1";
    try {
      const ctx = makeCtx(home);
      const expr = `const out = await ctx.bash({ command: "echo hi" }); return out.trim();`;
      const result = await ashlrPipe({ expr }, ctx);
      // The stub returns "stub-bash-output"; the expression trims it.
      expect(JSON.parse(result.text)).toBe("stub-bash-output");
      // Handler was actually invoked.
      expect(callLog.length).toBe(1);
    } finally {
      if (prev === undefined) delete process.env.ASHLR_PIPE_ALLOW_BASH;
      else process.env.ASHLR_PIPE_ALLOW_BASH = prev;
    }
  });

  test("read-only tools (grep, read, ls, glob) work without ASHLR_PIPE_ALLOW_BASH", async () => {
    // Confirm default ctx includes grep/read/ls/glob regardless of bash flag.
    const callLog: string[] = [];
    registerTool({
      name: "ashlr__grep",
      description: "stub",
      inputSchema: {},
      handler: makeStubHandler("grep-line", callLog),
    });

    delete process.env.ASHLR_PIPE_ALLOW_BASH;
    const ctx = makeCtx(home);
    const expr = `const r = await ctx.grep({ pattern: "x", cwd: "." }); return r.trim();`;
    const result = await ashlrPipe({ expr }, ctx);
    expect(JSON.parse(result.text)).toBe("grep-line");
    expect(callLog.length).toBe(1);
  });
});

