/**
 * Tests for ashlr__pipe (pipe-server.ts + pipe-server-handlers.ts).
 *
 * Run with: ASHLR_PIPE_ENABLE=1 bun test __tests__/pipe-server.test.ts
 *
 * Most tests exercise the core logic directly via ashlrPipe(); the handler
 * regression test also exercises the router over MCP stdio. Registry-based
 * ctx calls use real handlers where feasible and stubs for accounting tests.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { mkdtemp, readFile, rm, writeFile } from "fs/promises";
import { tmpdir } from "os";
import { join } from "path";
import { timingBudgetMs } from "../scripts/timing-budget.ts";

// NOTE: we deliberately do NOT set process.env.ASHLR_PIPE_ENABLE here. That env
// var only gates *registration* of ashlr__pipe in pipe-server-handlers.ts; the
// core ashlrPipe() function under test needs no flag. Setting it at module scope
// leaks process-wide and makes sibling test files that import _router-handlers
// register a 41st tool, breaking the tool-count assertions. See router-dispatch
// + product-metadata tests.

import { ashlrPipe, type PipeResult } from "../servers/pipe-server";
import {
  registerTool,
  __snapshotRegistryForTests,
  __restoreRegistryForTests,
  type ToolCallContext,
} from "../servers/_tool-base";
import { _withSuppressedAccounting, _isAccountingSuppressed } from "../servers/_stats";

describe("ashlr__pipe · handler error isolation", () => {
  test("invalid JavaScript returns tool errors and the server handles later calls, including grep with no matches", async () => {
    const fixture = join(home, "grep-fixture.txt");
    await writeFile(fixture, "needle first: complete text\nunrelated line\nneedle second: complete text\nneedle third: complete text\n");
    const proc = Bun.spawn({
      cmd: [process.execPath, "run", join(import.meta.dir, "../servers/_router.ts")],
      cwd: join(import.meta.dir, ".."),
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
      env: {
        ...process.env,
        HOME: home,
        ASHLR_PIPE_ENABLE: "1",
        ASHLR_STATS_SYNC: "1",
        ASHLR_SESSION_LOG: "0",
        ASHLR_CONTEXT_DB_DISABLE: "1",
        ASHLR_ALLOW_PROJECT_PATHS: home,
        ASHLR_GENOME_RETRIEVAL: "off",
      },
    });
    const reader = proc.stdout.getReader();
    const stderr = new Response(proc.stderr).text();
    const decoder = new TextDecoder();
    let pending = "";
    async function request(id: number, method: string, params: unknown) {
      proc.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
      while (!pending.includes("\n")) {
        const chunk = await reader.read();
        if (chunk.done) throw new Error(`router exited before response ${id}`);
        pending += decoder.decode(chunk.value, { stream: true });
      }
      const newline = pending.indexOf("\n");
      const response = JSON.parse(pending.slice(0, newline));
      pending = pending.slice(newline + 1);
      expect(response.id).toBe(id);
      return response;
    }

    try {
      const init = await request(1, "initialize", {
        protocolVersion: "2024-11-05",
        capabilities: {},
        clientInfo: { name: "pipe-test", version: "1" },
      });
      expect(init.result.serverInfo.name).toBe("ashlr-router");

